PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY, owner TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(ip TEXT NOT NULL, at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS entities(owner TEXT NOT NULL, id TEXT NOT NULL, kind TEXT NOT NULL, version INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(owner,id,kind));
CREATE TABLE IF NOT EXISTS mutations(owner TEXT NOT NULL, id TEXT NOT NULL, fingerprint TEXT NOT NULL, ack TEXT NOT NULL, PRIMARY KEY(owner,id));
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, owner TEXT NOT NULL, kind TEXT NOT NULL, entity_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_owner_seq ON events(owner,seq);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, owner TEXT NOT NULL, metadata TEXT NOT NULL, ready INTEGER NOT NULL DEFAULT 0, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS attachment_refs(owner TEXT NOT NULL, idea_id TEXT NOT NULL, attachment_id TEXT NOT NULL, PRIMARY KEY(owner,idea_id,attachment_id));
PRAGMA user_version=1;
